2	
3	// CONCURRENCY.md C4: taking a slot back to a checkpoint.
4	//
5	//	go test ./llm/ -v -run TestGraphCheckpointIsThePrefill   # four layers, ~9 GB
6	
7	import (
8		"fmt"
9		"os"
10		"strconv"
11		"testing"
12	)
13	
14	func probeN(k string, d int) int {
15		if v, err := strconv.Atoi(os.Getenv(k)); err == nil {
16			return v
17		}
18		return d
19	}
20	
21	// TestGraphCheckpointIsThePrefill is C4's gate. A prompt prefix is
22	// checkpointed, the slot runs on into a different continuation (a prompt
23	// tail and some decode steps, which move every recurrence and complete
24	// pooled indexer blocks past the checkpoint), and it is restored and run
25	// into the real tail. That must give **bit for bit** the logits of running
26	// prefix and tail with nothing in between.
27	//
28	// The prefix is 2600 tokens in a 4096-cell cache, which puts the indexer's
29	// selection past its width, so the pooled blocks decide which cells are read.
30	// The detour (600 tokens and 12 steps) runs further than the real
31	// continuation (300 and 12), so blocks it completed are still there, stale,
32	// when the real one decodes. That is the case in which Checkpoint's claim
33	// that the pooled table needs no restore could fail, and it does not. The
34	// sequence runs in slot 1 while slot 0 runs something else between the
35	// checkpoint and the restore, so the checkpoint is also checked to be the
36	// slot's and not the graph's.
37	//
38	// Each control leaves one part of the restore out, and each must move the
39	// logits. Otherwise the gate cannot tell that part of the restore from a
40	// no-op.
41	func TestGraphCheckpointIsThePrefill(t *testing.T) {
42		const (
43			layers = 4
44			chunk  = 1024
45			nKV    = 4096
46			prefix = 2600
47			steps  = 12
48		)
49		m, tr := fixtures4k(t)
50		all, _, err := tr.Tokens()
51		if err != nil {
52			t.Fatal(err)
53		}
54		if len(all) < 3600 {
55			t.Skipf("the 4k trace has %d tokens", len(all))
56		}
57		pre, tail, other := all[:prefix], all[prefix:prefix+300], all[3000:3600]
58	
59		dev, done := newTestDevice(t)
60		t.Cleanup(done)
61		g, err := NewGraph(dev, m, GraphOpts{MaxTokens: chunk, NKV: nKV, Layers: layers, Slots: 2})
62		if err != nil {
63			t.Fatal(err)
64		}
65		t.Cleanup(g.Destroy)
66		if !g.attn.sparse {
67			t.Fatalf("a %d-cell cache is not sparse, so the pooled blocks would not be under test", nKV)
68		}
69	
70		clone := func(l []float32) []float32 { return append([]float32(nil), l...) }
71		argmax := func(l []float32) int32 {
72			id := int32(0)
73			for j := range l {
74				if l[j] > l[id] {
75					id = int32(j)
76				}
77			}
78			return id
79		}
80		use := func(s int) {
81			if err := g.UseSlot(s); err != nil {
82				t.Fatal(err)
83			}
84		}
85		// feed runs ids through the live slot in `chunk`-wide passes, the first
86		// one fresh when asked, and returns the last pass's logits.
87		feed := func(ids []int32, fresh bool) []float32 {
88			var logits []float32
89			for at := 0; at < len(ids); at += chunk {
90				c := ids[at:min(at+chunk, len(ids))]
91				var err error
92				if fresh && at == 0 {
93					logits, _, err = g.Forward(c)
94				} else {
95					logits, _, err = g.Extend(c)
96				}
97				if err != nil {
98					t.Fatalf("%d tokens at %d: %v", len(c), g.Past(), err)
99				}
100			}
101			return logits
102		}
103		// finish runs the tail and then `steps` greedy decode steps, or the
104		// steps named when forced is non-nil, and returns every logit row.
105		finish := func(forced []int32) ([]int32, [][]float32) {
106			logits := feed(tail, false)
107			rows := [][]float32{clone(logits)}
108			var toks []int32
109			for i := range steps {
110				id := argmax(logits)
111				if forced != nil {
112					id = forced[i]
113				}
114				toks = append(toks, id)
115				var err error
116				if logits, _, err = g.Extend([]int32{id}); err != nil {
117					t.Fatal(err)
118				}
119				rows = append(rows, clone(logits))
120			}
121			return toks, rows
122		}
123	
124		// The reference: prefix then tail, nothing between. Twice, because the
125		// first run over fresh arenas is not bit-repeatable against later ones
126		// (TestPrerecordedDecodeIsTheRecordedDecode); slot 0 is warmed too.
127		use(0)
128		feed(other, true)
129		use(1)
130		feed(pre, true)
131		finish(nil)
132		feed(pre, true)
133		toks, want := finish(nil)
134	
135		// restore is Graph.Restore with a part optionally left out, for the
136		// controls. The full one is g.Restore itself.
137		type part int
138		const (
139			all3 part = iota
140			noDeltaNet
141			noPLE
142		)
143		restore := func(c *Checkpoint, skip part) {
144			if skip == all3 {
145				if err := g.Restore(c); err != nil {
146					t.Fatal(err)
147				}
148				return
149			}
150			if skip != noDeltaNet {
151				if err := g.dn.RestoreCarried(c.dn); err != nil {
152					t.Fatal(err)
153				}
154			}
155			if skip != noPLE {
156				if err := g.ple.RestoreCarried(c.ple); err != nil {
157					t.Fatal(err)
158				}
159			}
160			if err := g.rewindPosition(c.past, c.past); err != nil {
161				t.Fatal(err)
162			}
163		}
164	
165		var ck *Checkpoint
166		run := func(skip part) [][]float32 {
167			use(1)
168			feed(pre, true)
169			var err error
170			if ck, err = g.Checkpoint(ck); err != nil {
171				t.Fatal(err)
172			}
173			// Somewhere else first: the abandoned continuation, then the other
174			// slot's conversation, then back.
175			feed(other[:probeN("CK_DETOUR", len(other))], false)
176			for range probeN("CK_DSTEPS", steps) {
177				if _, _, err := g.Extend([]int32{toks[0]}); err != nil {
178					t.Fatal(err)
179				}
180			}
181			use(0)
182			feed(other, true)
183			use(1)
184			restore(ck, skip)
185			if g.Past() != prefix {
186				t.Fatalf("restored to position %d, want %d", g.Past(), prefix)
187			}
188			_, rows := finish(toks)
189			return rows
190		}
191	
192		firstDiff := func(got [][]float32) string {
193			for r := range want {
194				for j := range want[r] {
195					if got[r][j] != want[r][j] {
196						return fmt.Sprintf("row %d logit %d: %g against %g", r, j, got[r][j], want[r][j])
197					}
198				}
199			}
200			return ""
201		}
202	
203		if d := firstDiff(run(all3)); d != "" {
204			t.Fatalf("restoring the checkpoint is not the prefill: %s", d)
205		}
206		t.Logf("checkpoint at %d of %d cells, %d-token detour past it and %d steps, restored in slot 1 with "+
207			"slot 0 run between: %d logit rows bit-identical to prefix + tail", prefix, nKV, len(other), steps, len(want))
208	
209		for _, c := range []struct {
210			name string
211			skip part
212		}{
213			{"the deltanet state and rings", noDeltaNet},
214			{"the ple ring", noPLE},
215		} {
216			d := firstDiff(run(c.skip))
217			if d == "" {
218				t.Errorf("control: a restore without %s gives the same logits, so the gate cannot see it", c.name)
219				continue
220			}
221			t.Logf("control, without %s: moves at %s", c.name, d)
222		}
223	
224		// Restore refuses a slot that no longer holds the checkpoint's tokens:
225		// the cells below it are some other conversation's now.
226		use(1)
227		feed(other, true)
228		if err := g.Restore(ck); err == nil {
229			t.Error("Restore accepted a checkpoint after the slot was re-run from token zero with other tokens")
230		}
231	}

