			len(snap), hi-lo, len(g.layers))
	}
	for l := range g.layers {
		off := int(g.hIdxK) + l*g.idxKStride + lo*g.cfg.IdxDim
		g.ibuf.WriteUint16At(off, snap[l*n:(l+1)*n])
	}
	return nil
}

