// ---- P14-2: the per-cell gather, and it is the last large term in a prefill
// at depth.
//
// P13 closed the arithmetic of 900 tok/s at 128k and named one route to it. The
// selection skips cells; the kernel skips **blocks**; and at 128 000 cells a
// sixteen-row query tile's live 16-cell blocks hold 24 580 cells to do work on
// the 10 058 its rows actually selected. P13's block list deleted 83% of the
// *visits* and measured 1.00x, because the visits were never the cost — the
// cells were. This deletes the cells: a compaction one granularity finer, and a
// dense attention over what comes out.
//
// The three things that make it affordable, none of which P13 had:
//
//   - **The value plane is cell-major** (P14-2's other half). A selected run is
//     `ratio` consecutive cells, so a run is one 128-byte line per head-dim
//     group in both planes. Transposed, the value's run was four halves out of
//     each of sixteen rows — the whole tile read for a quarter of it.
//   - **The staging is a head-dim group, not a chunk.** 1 KB of LDS, not 32, so
//     the single-wave workgroups stay twenty-deep on a compute unit. Occupancy
//     is the one thing a prefill cannot trade (P13-3).
//   - **The causal test is in the mask.** The gather ANDs each row's own extent
//     into the bits it writes, so the loop has one predicate where the block
//     kernel had three.
//
// It is **prefill's and not decode's**, on P8's rule: a decode step is one query
// tile, its 24 single-wave workgroups all fit at once, and what it costs is one
// wave's serial walk — which a gather in front of it lengthens rather than cuts,
// on top of two dispatches it cannot amortise over 128 tiles.
const (
	// The narrowest query tile any gathered rung uses. The arena is sized for
	// it because the rung is a knob and the arena plan is fixed at
	// construction.
	gathBM = 16
	// The row count at or below which the gather is not taken: the decode
	// regime, where the split kernel owns the axis.
	gathMinRows = attnSplitMaxRows + 1
	// Head-dim groups staged per barrier, and it is a measured rung — see
	// gathGroups. 2 is 1.00x and 4 is 1.34x against, because the barriers were
	// never the cost.
	gathDefaultGroups = 1
	// Query heads a workgroup — see gathHeadsPerWG.
	gathDefaultHeads = 1
	// attnHeadRowsDefault is whether the gathered kernel puts heads on the
	// fragment's rows (P17) when nothing pins it.
	attnHeadRowsDefault = true
)

var gathPipes = map[string][]byte{
	"gather":       shaders.LLMAttnGatherBM16,
	"gathmask":     shaders.LLMAttnGathMaskBM16,
	"gath.qt1_kt1": shaders.LLMAttnGathQT1KT1,
	"gath.qt1_kt2": shaders.LLMAttnGathQT1KT2,
	"gath.qt1_kt4": shaders.LLMAttnGathQT1KT4,
	// P15's split-gather, the decode arm: the gathered axis cut `splits` ways
	// with `llm_attn_combine.comp` behind it.
	"gath.qt1_kt1_split": shaders.LLMAttnGathQT1KT1Split,
	"gath.qt1_kt2_split": shaders.LLMAttnGathQT1KT2Split,
	"gath.qt1_kt4_split": shaders.LLMAttnGathQT1KT4Split,
	"gath.qt1_kt1_g2":    shaders.LLMAttnGathQT1KT1G2,
	"gath.qt1_kt2_g2":    shaders.LLMAttnGathQT1KT2G2,
	"gath.qt1_kt4_g2":    shaders.LLMAttnGathQT1KT4G2,
	"gath.qt1_kt1_g4":    shaders.LLMAttnGathQT1KT1G4,
	"gath.qt1_kt2_g4":    shaders.LLMAttnGathQT1KT2G4,
	"gath.qt1_kt4_g4":    shaders.LLMAttnGathQT1KT4G4,
	"gath.qt1_kt1_h2":    shaders.LLMAttnGathQT1KT1H2,
	"gath.qt1_kt2_h2":    shaders.LLMAttnGathQT1KT2H2,
	"gath.qt1_kt4_h2":    shaders.LLMAttnGathQT1KT4H2,
	"gath.qt1_kt1_h4":    shaders.LLMAttnGathQT1KT1H4,
	"gath.qt1_kt2_h4":    shaders.LLMAttnGathQT1KT2H4,
	"gath.qt1_kt4_h4":    shaders.LLMAttnGathQT1KT4H4,
	// P17: heads on the fragment's rows, over a per-token list.
	gatherBM1:                  shaders.LLMAttnGatherBM1,
	"gath.qt1_kt1_hrows":       shaders.LLMAttnGathQT1KT1HRows,
	"gath.qt1_kt2_hrows":       shaders.LLMAttnGathQT1KT2HRows,
	"gath.qt1_kt4_hrows":       shaders.LLMAttnGathQT1KT4HRows,
	"gath.qt1_kt1_hrows_split": shaders.LLMAttnGathQT1KT1HRowsSplit,
	"gath.qt1_kt2_hrows_split": shaders.LLMAttnGathQT1KT2HRowsSplit,
	"gath.qt1_kt4_hrows_split": shaders.LLMAttnGathQT1KT4HRowsSplit,
}

// gatherBM1 is the gather's one-row build: each token's own selection,
// compacted, which is the list the heads-on-rows kernel reads (P17).
const gatherBM1 = "gather.bm1"

// headRows is whether the gathered attention puts a token's query heads on the
// fragment's rows instead of sixteen tokens of one head (P17, `-DHROWS` in
// llm_attn_wmma.comp).
//
// The selection is per token and twelve query heads share each kv head, so the
// twelve rows of one token select the same cells against the same key: the
// list is that token's 2051 cells rather than a sixteen-token union (7049 at
// 128 000 cells), the per-row mask pass is gone, and the kv plane is staged
// once for twelve heads. It needs `rep <= 16` and `heads >= 16` — a fragment is
// sixteen rows and the clamp `h0 = min(g*rep, heads-16)` keeps every Q load
// inside the plane — and it is refused back to the token-row kernel otherwise.
//
// LLM_ATTN_GATHER_HROWS=0 is the control arm.
func (g *AttnGPU) headRows() bool {
	if g.pinHRows != 0 {
		return g.pinHRows > 0 && g.hrowsFits()
	}
	if v := os.Getenv("LLM_ATTN_GATHER_HROWS"); v != "" {
		return v == "1" && g.hrowsFits()
	}
	if !attnHeadRowsDefault || !g.hrowsFits() {
		return false
	}
	// Decode: one row, where the token fragment's union *is* the token's
	// selection, so the two builds are the same bits and this one skips the
	// mask pass (TestAttnGPUHeadRowsIsTheGather).
	if g.rows <= attnSplitMaxRows {
		return true
	}
	// Prefill: only once there is past to be sparse over. From a cold cache
	// the selection names every live cell, a token tile's union is one row's,
	// and twelve heads on sixteen rows is a quarter of the fragment wasted for
	// nothing. Measured on the 4-layer probe at ubatch 2048 (tok/s, two runs):
	//
	//	past        0     2048    4096    8192   16384  128000
	//	tokens  11109   10406   10162    9818    9424    7817
	//	heads   11076   10504   10590   10529   10500   10271
	return g.past >= g.hrowsMinPast()
}

// hrowsMinPast is the prefill bound above; LLM_ATTN_GATHER_HROWS_MIN overrides.
func (g *AttnGPU) hrowsMinPast() int {
	if n, err := strconv.Atoi(os.Getenv("LLM_ATTN_GATHER_HROWS_MIN")); err == nil && n >= 0 {
		return n

