func (g *AttnGPU) Score() []float32 {
	nb := g.NBlocks()
	out := g.abuf.ReadFloat32At(int(g.aScore), g.rows*nb)
	nBid := (g.past + g.rows) / g.cfg.Ratio
	if nBid >= nb {
		return out
	}
	for t := 0; t < g.rows; t++ {
		row := out[t*nb : (t+1)*nb]
		for b := nBid + 1; b < nb; b++ {
			row[b] = row[nBid]
		}
	}
	return out
}

