 llm/graph_checkpoint_test.go | 184 ++++++++++++++++++++++++++++++++++++++++++-
 1 file changed, 182 insertions(+), 2 deletions(-)
272 shaders/llm_attn_pack.comp
#version 450

#extension GL_EXT_shader_16bit_storage : require
#extension GL_EXT_shader_explicit_arithmetic_types_float16 : require
#extension GL_EXT_control_flow_attributes : require


#include "llm_common.glsl"

#define TILE 16
#ifndef HEAD_DIM
#define HEAD_DIM 256
#endif
#define HDT (HEAD_DIM / TILE)
#define WG 256

layout(local_size_x = WG) in;

shared float rows[TILE * HEAD_DIM];
shared float part[TILE * TILE];

void main() {
    uint tt = gl_WorkGroupID.x;      // token tile
    uint p = gl_WorkGroupID.y;       // which plane: query, key or value head
    uint tid = gl_LocalInvocationID.x;
    uint tok0 = tt * TILE;

    uint qWidth = pc.heads * 2u * pc.headDim;
    uint kvWidth = pc.kvHeads * pc.headDim;
    uint past = SEQ_PAST;

    if (p == pc.heads + 2u * pc.kvHeads) {
        uint idxKCol = qWidth + 2u * kvWidth + pc.idxHeads * pc.idxDim;
        for (uint i = tid; i < TILE * pc.idxDim; i += WG) {
            uint m = i / pc.idxDim, d = i % pc.idxDim;
            uint token = tok0 + m;
            if (token >= pc.tokens) {
                continue;
            }
            icache[ATTN_IDXRAW + (past + token) * pc.idxDim + d] =
                float16_t(act[pc.qkvOff + token * pc.gemmN + idxKCol + d]);
        }
        return;
    }

    uint head, srcCol, gamma, outOff;
    bool rot;
    bool cached;                     // key and value: cells, not token rows
    uint mode;                       // 0 natural tiles, 1 transposed
    float scale = 1.0;
    if (p < pc.heads) {
        head = p;
        srcCol = head * 2u * pc.headDim;   // the query half of this head
        gamma = pc.gammaOff;
        outOff = pc.qOff;
        rot = true;
        cached = false;
        mode = 0u;
        scale = uintBitsToFloat(pc.attnScale);
    } else if (p < pc.heads + pc.kvHeads) {
        head = p - pc.heads;
        srcCol = qWidth + head * pc.headDim;
        gamma = pc.gammaKOff;
        outOff = pc.kOff;
        rot = true;
        cached = true;
        mode = 0u;
    } else {
        head = p - pc.heads - pc.kvHeads;
        srcCol = qWidth + kvWidth + head * pc.headDim;
        gamma = NO_W;
        outOff = pc.vOff;
        rot = false;
        cached = true;
        mode = 0u;
    }

    for (uint i = tid; i < TILE * HEAD_DIM; i += WG) {
        uint m = i / HEAD_DIM, d = i % HEAD_DIM;
        uint token = tok0 + m;
        rows[i] = (token < pc.tokens)
            ? act[pc.qkvOff + token * pc.gemmN + srcCol + d]
            : 0.0;
    }
    barrier();

    if (gamma != NO_W) {
        uint m = tid / TILE, lane = tid % TILE;
        float s = 0.0;
        for (uint d = lane; d < HEAD_DIM; d += TILE) {
            float v = rows[m * HEAD_DIM + d];
            s += v * v;
        }
        part[tid] = s;
        barrier();
        for (uint stride = TILE / 2u; stride > 0u; stride >>= 1u) {
            if (lane < stride) {
                part[tid] += part[tid + stride];
            }
            barrier();
        }
        float inv = 1.0 / sqrt(part[m * TILE] / float(HEAD_DIM) + uintBitsToFloat(pc.eps));
        for (uint d = lane; d < HEAD_DIM; d += TILE) {
            rows[m * HEAD_DIM + d] *= inv * wbuf[gamma + d];
        }
        barrier();
    }

    if (rot) {
        uint rotHalf = pc.rotDims / 2u;
        uint pairs = TILE * rotHalf;
        uint sinTab = pc.ropeOff + pc.nKV * rotHalf;
        for (uint i = tid; i < pairs; i += WG) {
            uint m = i / rotHalf, j = i % rotHalf;
            uint pos = past + tok0 + m;
            if (pos >= pc.nKV) {
                continue;            // a pad row: its rotation is unobservable
            }
            float c = wbuf[pc.ropeOff + pos * rotHalf + j];
            float s = wbuf[sinTab + pos * rotHalf + j];
            uint b = m * HEAD_DIM + j;
            float lo = rows[b], hi = rows[b + rotHalf];
            rows[b] = lo * c - hi * s;
            rows[b + rotHalf] = lo * s + hi * c;
        }
        barrier();
    }

    uint base = outOff + (head * (pc.plane / TILE) + tt) * (HDT * TILE * TILE);
    uint cellTiles = pc.nKV / TILE;
    for (uint o = tid; o < HDT * TILE * TILE; o += WG) {
        uint c = o / (TILE * TILE);
        uint rem = o % (TILE * TILE);
        uint m, d;
        if (mode == 0u) {
            m = rem / TILE;              // (token, component)
            d = c * TILE + rem % TILE;
        } else {
            m = rem % TILE;              // transposed: (component, token)
            d = c * TILE + rem / TILE;
        }
        float v = rows[m * HEAD_DIM + d] * scale;
        if (!cached) {
            hact[base + o] = float16_t(v);
            continue;
        }
        uint token = tok0 + m;
        if (token >= pc.tokens) {
            continue;                    // a pad row is not a cell
        }
        uint cell = past + token;
        uint dst = outOff + (head * cellTiles + cell / TILE) * (HDT * TILE * TILE)
            + c * (TILE * TILE)
            + ((mode == 0u) ? (cell % TILE) * TILE + rem % TILE
                            : (rem / TILE) * TILE + cell % TILE);
        if (p < pc.heads + pc.kvHeads) {
