            continue;                    // a pad row is not a cell
        }
        uint cell = past + token;
        uint dst = outOff + (head * cellTiles + cell / TILE) * (HDT * TILE * TILE)
            + c * (TILE * TILE)
            + ((mode == 0u) ? (cell % TILE) * TILE + rem % TILE
                            : (rem / TILE) * TILE + cell % TILE);
        if (p < pc.heads + pc.kvHeads) {
            kcache[dst] = float16_t(v);
