// graph builds one layer's dispatch sequence, with a label per dispatch, and
// is shared by Run and Profile so that what the profiler times is what a run
// executes.
func (g *DeltaNetGPU) graph(layer int) ([]vk.MultiDispatch, []string, error) {
	if layer < 0 || layer >= len(g.layers) {
		return nil, nil, fmt.Errorf("llm: layer %d of %d", layer, len(g.layers))
	}
	c := g.cfg
	w := g.layers[layer]
	sv, _ := dnVariantFor(g.scan)
	gv, _ := gemmVariantFor(g.gemm)
	ov, _ := gemmVariantFor(g.outGemm)

	norm := uint32(0)
	if c.QKNorm == L2Max {
		norm = 1
	}
	base := push{
		Tokens: uint32(g.rows), NEmbd: uint32(c.NEmbd),
		LDA: uint32(g.lda), LDCtx: uint32(g.ldCtx), Eps: math.Float32bits(c.Eps),
		QKVOff: g.aQKV, NormOff: g.aNorm, OutOff: g.aOut, CtxOff: g.hCtx,
		ConvOff: w.conv, GammaOff: w.gamma, Kern: uint32(c.Conv),
		ConvOutOff: noW,
		SSMGateOff: g.aGate, SSMBetaOff: g.aBeta, SSMStateOff: g.stateAt(layer, g.stateSlot),
		SSMAOff: w.a, SSMDTOff: w.dtBias, SSMNorm: norm,
		Heads: uint32(c.NHeadV), KVHeads: uint32(c.NHeadK), HeadDim: uint32(c.HeadDim),
		GemmN: uint32(g.qkvN()),
		// SEQ_HIST: a field this layer does not otherwise use, because the
		// push block is full at 64 uints (llm_common.glsl). The position is
		// not here any more: SEQ_PAST is dword 0 of the arena (P1c), written
		// by SetPast, so `lowRank` stays zero and the dispatch is
		// byte-identical every decode step.
		//
		// The ring the convolution *reads* is the committed slot; the ring
		// the `hist` dispatch below writes is the one this pass is allowed to
		// throw away, which is the same slot in every pass but a speculative
		// one (P5c).
		InjOff: g.winAt(layer, g.stateSlot),
		// SSM_STATE_DST, the scan's destination. `resOff` is the
		// hyper-connection block's wide residual and never reaches this one,
		// so it is spare — the two decode GEMVs below already borrow it for
		// their partial sums, and they are the only dispatches here that do.
		ResOff: g.stateAt(layer, g.stateDst()),
	}
	if g.keepSilu {
		base.ConvOutOff = g.aSilu
	}

	var d []vk.MultiDispatch
	var kinds []string
	add := func(pipe, kind string, gx, gy uint32, pc push) {
		d = append(d, vk.MultiDispatch{Pipeline: g.pipes[pipe], GroupsX: gx, GroupsY: gy, PushConstants: pc.bytes()})
		kinds = append(kinds, kind)
	}

	// 1. The one fused projection: four of llama.cpp's matrices, one matmul.
	//    Alpha and beta are on the quantised plane with the rest of the
	//    family (D13's payoff, P2), so no field states a split.
	qkv := base
	qkv.XnOff, qkv.OutOff, qkv.BOff = g.hXn, g.aQKV, w.qkv
	qkv.GemmM, qkv.GemmK = uint32(roundUpInt(g.rows, gv.bm)), uint32(c.NEmbd)
	gy := uint32(roundUpInt(g.rows, gv.bm) / gv.bm)
	if ks := gemvSlabs(g.qkvGemv); ks > 0 {
		// The decode kernel: one row, so the parallelism comes from K and not
		// from a sixteen-row fragment of which fifteen rows are padding
		// (L8d-4). The partials ride `resOff`, which this block does not use.
		qkv.ResOff = g.aPart
		add(gemvBankPipeRows(g.qkvGemv, g.bank, g.rows), "qkv", uint32(ks), uint32(g.qkvN()/16), qkv)
		if ks > 1 {
			add(gemvSumPipeRows(g.qkvGemv, g.rows), "qkv.sum",
				uint32(roundUpInt(g.qkvN(), dnWave)/dnWave), uint32(g.rows), qkv)
		}
	} else if g.quant() {
		add(bankPipe(g.bank, g.gemm), "qkv", uint32(g.qkvN()/dnBN), gy, qkv)
	} else {
		add(string(g.gemm), "qkv", uint32(g.qkvN()/dnBN), gy, qkv)
	}

	// 2. The convolution, its SiLU, the two L2 norms and the two per-head
	//    scalars. One plane per head, plus one for the scalars.
	planes := uint32(2*c.NHeadK + c.NHeadV + 1)
	hist := c.Conv - 1
	if g.batch == nil {
		add("conv", "conv", planes, uint32(g.rows), base)

		// 3. The delta rule.
		add(string(g.scan), "scan", uint32(c.NHeadV), uint32(c.HeadDim/sv.cols()), base)

		// 4. The gated output norm, into the output projection's A operand.
		add("norm", "norm", uint32(c.NHeadV), uint32(g.rows), base)
	} else {
		// A batched decode pass (CONCURRENCY.md C5, batch.go): steps 2-4
		// and the ring write of step 6, once per row, as a one-token pass
		// of that row's sequence — its state and ring, its position at
		// dword 1+r, its rows of every per-token tensor. The scan carries
		// state from token to token, so rows of different sequences cannot
		// share one.
		for r, br := range g.batch {
			rb := base
			rb.Tokens, rb.LowRank = 1, uint32(1+r)
			rb.QKVOff += uint32(r * g.qkvN())
			rb.NormOff += uint32(r * c.ConvWidth())
			if rb.ConvOutOff != noW {
				rb.ConvOutOff += uint32(r * c.ConvWidth())
			}
			rb.OutOff += uint32(r * c.Inner)
			rb.CtxOff += uint32(r * g.ldCtx)
			rb.SSMGateOff += uint32(r * c.NHeadV)
			rb.SSMBetaOff += uint32(r * c.NHeadV)
			rb.SSMStateOff = g.stateAt(layer, br.slot)
			rb.ResOff = rb.SSMStateOff
			rb.InjOff = g.winAt(layer, br.slot)
			add("conv", "conv", planes, 1, rb)
			add(string(g.scan), "scan", uint32(c.NHeadV), uint32(c.HeadDim/sv.cols()), rb)
			add("norm", "norm", uint32(c.NHeadV), 1, rb)
			win := rb
			win.LoOff = rb.QKVOff // SEQ_SRC
			win.GemmM, win.GemmK = uint32(hist), uint32(g.qkvN())
			win.OutOff = noW
			add("hist", "hist", uint32((g.qkvN()+255)/256), 1, win)
		}
	}

	// 5. The output projection.
	out := base
	out.XnOff, out.LDA = g.hCtx, uint32(g.ldCtx)
	out.OutOff, out.BOff = g.aResult, w.out
	out.GemmM, out.GemmN, out.GemmK = uint32(roundUpInt(g.rows, ov.bm)), uint32(c.NEmbd), uint32(c.Inner)
	outPipe := string(g.outGemm)
	if g.quant() {
		outPipe = bankPipe(g.bank, g.outGemm)
	}
	if ks := gemvSlabs(g.outGemv); ks > 0 {
		out.ResOff = g.aPart
		add(gemvBankPipeRows(g.outGemv, g.bank, g.rows), "out", uint32(ks), uint32(c.NEmbd/16), out)
		if ks > 1 {
			add(gemvSumPipeRows(g.outGemv, g.rows), "out.sum",
				uint32(roundUpInt(c.NEmbd, dnWave)/dnWave), uint32(g.rows), out)
		}
	} else {
		add(outPipe, "out", uint32(c.NEmbd/dnBN), uint32(roundUpInt(g.rows, ov.bm)/ov.bm), out)
	}

	// 6. The convolution's window, for whatever runs next: the last Conv-1
	//    rows of the projection into this layer's ring. Three rows of 16512
	//    floats — 198 KB — and the only dispatch here a single-shot prefill
	//    does not need. A batched pass wrote each row's above.
	if g.batch != nil {
		return d, kinds, nil
	}
	win := base
	win.LoOff = g.aQKV // SEQ_SRC
	win.InjOff = g.winAt(layer, g.stateDst())
	win.GemmM, win.GemmK = uint32(hist), uint32(g.qkvN())
	// SEQ_HIST_PREV, and the grid with it. A pass that writes the ring it
	// read leaves the slots it did not produce alone — they are already
	// right, which is what makes this dispatch a pure write and what lets a
	// one-token decode step store one row. A speculative pass writes the
	// *other* ring, which is empty, so every slot has to be written and the
	// ones this pass did not produce are carried over.
	win.OutOff = noW
	rings := minInt(g.rows, hist)
	if g.stateSpec {
		win.OutOff, rings = g.winAt(layer, g.stateSlot), hist
	}
	add("hist", "hist", uint32((g.qkvN()+255)/256), uint32(rings), win)
	return d, kinds, nil
}

