    if (r != VK_SUCCESS) {
        return r;
    }

    r = vkResetFences(device, 1, &rec->fence);
    if (r != VK_SUCCESS) {
        return r;
    }

    VkSubmitInfo submitInfo = {0};
    submitInfo.sType = VK_STRUCTURE_TYPE_SUBMIT_INFO;
    submitInfo.commandBufferCount = 1;
    submitInfo.pCommandBuffers = &rec->cmdBuf;

